class MinStack:
    """
    155. 最小栈 - 双栈实现

    核心思想：
    主栈正常存数据，辅助栈存每个状态下的最小值。
    这样 getMin() 永远是 O(1)。

    时间复杂度：所有操作 O(1)
    空间复杂度：O(n)
    """

    def __init__(self):
        self.stack = []
        self.min_stack = [2**31]

    def push(self, x: int) -> None:
        self.stack.append(x)
        self.min_stack.append(min(x, self.min_stack[-1]))

    def pop(self) -> None:
        self.stack.pop()
        self.min_stack.pop()

    def top(self) -> int:
        return self.stack[-1]

    def getMin(self) -> int:
        return self.min_stack[-1]


class MinStack2:
    """
    155. 最小栈 - 单栈元组实现

    核心思想：
    每个栈元素存储 (val, 当前最小值)，用栈底哨兵简化空栈判断。
    """

    def __init__(self):
        self.st = [(0, 2**31)]

    def push(self, val: int) -> None:
        self.st.append((val, min(self.st[-1][1], val)))

    def pop(self) -> None:
        self.st.pop()

    def top(self) -> int:
        return self.st[-1][0]

    def getMin(self) -> int:
        return self.st[-1][1]
